  // ---- llm/stream lossless tap → segment → enqueue ----
  const sessionSegmenters = new Map<string, SentenceSegmenter>()

  ctx.on('llm/stream', (options: GenerateOptions, next: () => AsyncIterable<StreamChunk>) => {
